"""Original cooking plans used by the official recipe collection."""
PLANS={
'PORRIDGE':('Ніжна каша з м’якою кремовою текстурою.', [('Зваріть основу','8–12 хв','З’єднайте пластівці з молоком та/або водою з переліку. Доведіть до слабкого кипіння й варіть, помішуючи, до м’якості та бажаної густоти.'),('Додайте смакові складники','3 хв','Вмішайте передбачені рецептом підсолоджувачі та прянощі. М’які фрукти, горіхи й сир залиште для подачі, якщо в пораді не вказано інакше.')]),
'GRAIN':('Тепла молочна каша, у якій крупа зберігає приємну текстуру.', [('Приготуйте крупу','15–25 хв','Промийте крупу. Залийте зазначеною водою, доведіть до кипіння й варіть під кришкою на слабкому вогні. Для рису потрібно близько 18 хвилин, пшона й кіноа — 15–20, амаранту — 25.'),('Завершіть кашу','5–8 хв','Додайте молоко або кокосове молоко й підсолоджувач із переліку. Прогрівайте, помішуючи, до кремової консистенції. Фрукти й горіхи підготуйте для подачі з урахуванням поради.')]),
'CORN':('Густа кукурудзяна каша з ніжною вершковою основою.', [('Заваріть крупу','3 хв','Доведіть воду з молоком до кипіння. Тонкою цівкою всипте кукурудзяну крупу, постійно перемішуючи вінчиком, щоб не було грудочок.'),('Доведіть до готовності','15–20 хв','Варіть на мінімальному вогні, часто помішуючи. Наприкінці вмішайте масло та передбачений сир. Для версії з грибами обсмажте їх окремо й викладіть зверху.')]),
'OMELET':('Пухка яєчна страва із соковитою начинкою.', [('Підготуйте начинку','5–8 хв','Овочі та гриби дрібно наріжте. На зазначеній олії або маслі обсмажте щільні овочі та гриби до м’якості; зелень додайте наприкінці. Яйця збийте з молоком та сіллю з переліку.'),('Приготуйте омлет','6–8 хв','Зменште нагрів, влийте яйця на начинку та розподіліть сир, якщо він є у складі. Накрийте й готуйте до повного схоплювання яєць; для страви з яєць орієнтир у центрі — 71 °C.')]),
'FRITTATA':('Рум’яна яєчна запіканка з овочами та сиром.', [('Підготуйте основу','8–10 хв','Овочі наріжте невеликими шматочками й припустіть на зазначеній олії до м’якості. Уже варену картоплю чи горошок достатньо прогріти. Яйця злегка збийте, сир натріть.'),('Запечіть фритату','15–20 хв','Змішайте овочі з яйцями, викладіть у жаростійку форму та посипте сиром. Випікайте при 180 °C до повного схоплювання середини, орієнтир — 71 °C.')]),
'SHAKSHUKA':('Яйця у густій овочевій основі з насиченим томатним смаком.', [('Зробіть овочеву основу','12–15 хв','У зазначеній олії припустіть цибулю та перець, якщо він є у складі. Додайте подрібнені томати, часник і прянощі. Уваріть соус до густоти; варену квасолю прогрійте в ньому наприкінці.'),('Додайте яйця','7–10 хв','Зробіть у соусі заглиблення та обережно вбийте яйця. Готуйте під кришкою на слабкому вогні до повного схоплювання білків і жовтків; орієнтир у яєчній частині — 71 °C.')]),
'SCRAMBLE':('М’які яєчні пластівці з ніжним вершковим смаком.', [('Приготуйте яйця','7–9 хв','Яйця збийте з молоком і сіллю. Розтопіть масло на слабкому вогні, влийте суміш і перемішуйте лопаткою до повної готовності без рідких ділянок.'),('Підсушіть хліб','2–3 хв','Паралельно підсушіть хліб на сухій сковороді. Викладіть готові яйця та посипте зеленою цибулею.')]),
'HASH':('Підрум’янена картопля з овочами та ситною яєчною основою.', [('Обсмажте овочі','18–22 хв','На олії готуйте дрібні кубики картоплі під кришкою 12–15 хвилин, часто перемішуючи. Додайте цибулю й перець та смажте до м’якості картоплі й рум’яних країв.'),('Приготуйте яйця','7–9 хв','Зробіть у картоплі заглиблення, додайте яйця й накрийте кришкою. Доведіть яєчну частину до повної готовності, без рідких білків і жовтків.')]),
'COTTAGE':('Рум’яні сирники з м’якою сирною серединкою.', [('Замісіть сирну масу','7 хв','Сир відіжміть, розітріть із яйцем і цукром. Вмішайте борошно та інші сухі складники зі списку; родзинки, цедру або посічений шоколад додайте відповідно до поради. Сформуйте невеликі пласкі сирники.'),('Обсмажте','10–14 хв','Розігрійте зазначену олію. Смажте сирники на помірно слабкому вогні по 4–5 хвилин з кожного боку, потім потримайте під кришкою ще 2–3 хвилини до готовності середини.')]),
'PANCAKE':('М’які невеликі панкейки з легкою рум’яною поверхнею.', [('Змішайте тісто','7 хв','Окремо змішайте борошно з розпушувачем, а яйце — з молоком. З’єднайте, додайте передбачене фруктове пюре. Не вимішуйте довго. Якщо йогурт і мед призначені для соусу, залиште їх окремо.'),('Випечіть на сковороді','10–12 хв','Змастіть сковороду частиною зазначеної олії. Викладайте тісто невеликими порціями. Смажте по 2–3 хвилини з кожного боку до готовності середини; витратьте решту олії на наступні порції.')]),
'FRITTER':('Невеликі оладки з рум’яними краями та м’якою серединою.', [('Зробіть густе тісто','8 хв','Овочі або фрукти натріть, зайву вологу відіжміть. Змішайте з яйцями, борошном і зазначеними добавками. Кефір, цукор і розпушувач додавайте лише там, де вони є у складі.'),('Підсмажте оладки','12–16 хв','На зазначеній олії смажте невеликі пласкі оладки по 3–4 хвилини з кожного боку на помірному вогні. Середина має повністю приготуватися; за потреби доготуйте під кришкою.')]),
'CREPE':('Тонкі домашні млинці з ніжною начинкою.', [('Приготуйте тісто','8 хв','Збийте яйця з молоком, додайте борошно та частину олії. Какао або подрібнений шпинат вмішайте, якщо вони є у складі. Цукор розділіть між тістом і начинкою за порадою. Дайте тісту постояти 5 хвилин.'),('Спечіть млинці й підготуйте начинку','15–20 хв','Розігрійте сковороду й змащуйте рештою олії. Наливайте тісто тонким шаром і смажте з обох боків до готовності. Сир, фрукти або соус підготуйте за порадою та загорніть у готові млинці.')]),
'TOAST':('Хрустка хлібна основа з соковитою свіжою начинкою.', [('Приготуйте основу','3–5 хв','Хліб підсушіть у тостері або на сухій сковороді. Овочі й фрукти помийте, обсушіть і наріжте відповідно до поради.'),('Зберіть тости','5 хв','Підготуйте намазку зі складників рецепта, розподіліть на теплому хлібі. Додайте решту начинки, зелень і зазначену заправку. Подавайте одразу, доки хліб хрусткий.')]),
'BAKED_TOAST':('Гарячі тости з розплавленим сиром і виразною начинкою.', [('Зберіть тости','7 хв','Розігрійте духовку до 190 °C. Хліб викладіть на пергамент. Розподіліть тонко нарізані складники начинки та сир; масло чи олію використайте, якщо вони є у переліку.'),('Запечіть','7–10 хв','Запікайте до розплавлення сиру та рум’яних країв хліба. Передбачені мед, зелень чи горіхи додайте з урахуванням поради, не залишаючи їх на тривалий нагрів.')]),
'YOGURT':('Прохолодна вершкова основа з соковитими фруктами й текстурними добавками.', [('Підготуйте фрукти','5 хв','Видаліть кісточки й неїстівну шкірку, фрукти наріжте, ягоди обсушіть. Горіхи чи насіння підготуйте за порадою.'),('Зберіть порції','3–5 хв','Розподіліть йогурт або сирну основу між мисками. Додайте фрукти, мед та зазначені прянощі. Горіхи й насіння викладіть зверху безпосередньо перед подачею.')]),
'OVERNIGHT':('Густа холодна вівсянка, що стає ніжною за ніч.', [('Змішайте основу','7 хв','У банках або контейнері з кришкою змішайте пластівці, молоко, йогурт і насіння, якщо воно зазначене. Додайте підсолоджувач та какао або частину фруктів за порадою.'),('Залиште в холодильнику','6 год','Закрийте й охолоджуйте щонайменше 6 годин. Перемішайте перед подачею, додайте відкладені фрукти. Пластівці повинні повністю ввібрати рідину й розм’якшитися.')]),
'CHIA':('Ніжний холодний пудинг із виразною зернистою текстурою чіа.', [('Змішайте й дайте набухнути','10 хв','З’єднайте насіння чіа з молоком або кокосовим молоком, підсолоджувачем та іншими складниками основи. Через 10 хвилин знову ретельно перемішайте.'),('Охолодіть','4 год','Накрийте та поставте в холодильник щонайменше на 4 години. Фрукти та ягоди підготуйте за порадою і додайте перед подачею.')]),
'BAKED_OATS':('Запечена вівсянка з м’якою серединою та злегка рум’яним верхом.', [('Підготуйте суміш','10 хв','Розігрійте духовку до 180 °C. Збийте яйця з молоком і підсолоджувачем, додайте пластівці, прянощі й підготовлені фрукти. Форму змастіть зазначеним маслом.'),('Запечіть','25–30 хв','Викладіть суміш у форму шаром до 4 см. Випікайте до повного схоплювання середини, орієнтир — 71 °C. Дайте постояти 5 хвилин перед нарізанням.')]),
'CASSEROLE':('М’яка сирна запіканка з рівномірно пропеченою серединою.', [('Замісіть основу','10–15 хв','Розігрійте духовку до 180 °C, форму змастіть указаним маслом. Розітріть сир із яйцями та борошном або манкою. Додайте решту складників за порадою; манці дайте набухнути 10 хвилин.'),('Запечіть','30–35 хв','Перекладіть у форму шаром 3–4 см. Випікайте до рум’яного верху й повної готовності середини, орієнтир — 71 °C. Дайте стабілізуватися 5 хвилин.')]),
'QUESADILLA':('Підсмажена тортилья з тягучим сиром та соковитою начинкою.', [('Зробіть начинку','7 хв','Готові бобові чи кукурудзу відцідіть, овочі наріжте дрібно, сир натріть. Начинку змішайте й розподіліть на половині кожної тортильї; накрийте другою половиною.'),('Обсмажте','6–8 хв','Змастіть сковороду зазначеною олією. Готуйте складені тортильї по 3–4 хвилини з кожного боку, притискаючи лопаткою, до повного розплавлення сиру. Наріжте трикутниками.')]),
'WRAP':('М’який рулет із тонкого хліба та свіжої начинки.', [('Підготуйте начинку','10 хв','Овочі наріжте соломкою, листя обсушіть. Сир або бобову намазку приготуйте за порадою. Якщо в начинці є яйця чи курка, спочатку повністю приготуйте їх відповідно до окремого кроку нижче.'),('Сформуйте рулети','5 хв','Лаваш або тортилью змастіть передбаченим соусом, розкладіть начинку, залишаючи вільні краї. Підігніть краї та щільно загорніть. Розріжте навпіл гострим ножем.')]),
'COUSCOUS':('Розсипчастий кускус із виразними смаковими додатками.', [('Запарте кускус','7 хв','Кускус залийте зазначеною киплячою водою, накрийте і залиште на 5–7 хвилин або на час, вказаний на упаковці.'),('Додайте решту складників','5 хв','Розпушіть виделкою, вмішайте масло або олію. Додайте підготовлені сухофрукти й горіхи; для овочевої версії овочі попередньо обсмажте 8–10 хвилин, а готовий нут прогрійте разом із ними.')]),
'FRIED_RICE':('Розсипчастий рис зі швидко обсмаженими добавками.', [('Підготуйте додатки','6–8 хв','На половині олії доведіть яйця до повної готовності й тимчасово перекладіть у миску. На решті олії прогрійте овочі; для версії з креветками приготуйте їх до непрозорої середини.'),('Обсмажте рис','5–7 хв','Додайте вже варений рис, розбийте грудочки лопаткою та добре прогрійте. Поверніть яйця, влийте соєвий соус, перемішайте й додайте зелену цибулю.')]),
'SALAD':('Соковитий салат із контрастом свіжих складників та заправки.', [('Підготуйте складники','7–10 хв','Овочі, фрукти й зелень помийте та обсушіть. Наріжте у зручний для виделки розмір. Уже варені крупи й бобові відцідіть; консервовану рибу відокремте від рідини.'),('Заправте салат','3–5 хв','Змішайте зазначені олію, цитрусовий сік, оцет, гірчицю або йогурт у заправку. Поєднайте складники, ніжний сир і листя додавайте останніми. Горіхи чи насіння залиште для верху.')]),
'SOUP':('Насичений домашній суп із м’якими овочами та виразним бульйоном.', [('Почніть овочеву основу','8–10 хв','У каструлі на зазначеній олії припустіть цибулю та моркву. Додайте подрібнені томати або томатну пасту, якщо вони є у складі, й прогрійте 2 хвилини.'),('Зваріть суп','20–30 хв','Влийте зазначену воду, додайте сирі крупи й щільні овочі з урахуванням поради. Варіть при слабкому кипінні до повної м’якості. Готові бобові та варену пасту додавайте наприкінці, щоб вони не розварилися.')]),
'CREAM_SOUP':('Оксамитовий овочевий крем-суп із м’яким смаком.', [('Зваріть овочі','20–25 хв','На олії або маслі припустіть цибулю, додайте нарізані овочі й зазначену воду. Варіть до повної м’якості; готовий зелений горошок додавайте наприкінці.'),('Зробіть кремову текстуру','5 хв','Зніміть з нагріву та обережно подрібніть занурювальним блендером. Вмішайте молоко чи вершки та прогрійте. Йогурт, якщо він є у складі, додавайте після зняття з вогню, не кип’ятіть.')]),
'MISO':('Легкий суп із м’яким тофу, водоростями та смаком умамі.', [('Зваріть основу','10–12 хв','Водорості замочіть на 5 хвилин у частині зазначеної води. Решту води нагрійте з нарізаними грибами, варіть 7–8 хвилин. Додайте тофу кубиками та підготовлені водорості.'),('Додайте місо','3 хв','Вимкніть нагрів. Розведіть місо-пасту невеликою кількістю гарячого бульйону та поверніть у каструлю. Перемішайте, додайте зелену цибулю і більше не кип’ятіть.')]),
'GRAIN_SAVORY':('Розсипчаста крупа з підрум’яненими овочами.', [('Зваріть крупу','20–45 хв','Промийте крупу, залийте зазначеною водою й варіть під кришкою на слабкому вогні до м’якості. Гречці потрібно 18–22 хвилини, перловці — 40–45; за потреби підливайте технічну воду.'),('Приготуйте додатки','10–15 хв','На олії або маслі обсмажте цибулю та інші овочі, гриби доведіть до випаровування вологи. Змішайте з готовою крупою, посоліть указаною сіллю й прогрійте 2 хвилини.')]),
'PILAF':('Ситна страва з розсипчастою крупою та соковитою куркою.', [('Обсмажте основу','10–12 хв','Рис або булгур промийте, курку наріжте кубиками до 2 см. У широкій каструлі на олії підрум’яньте курку, потім припустіть нарізані овочі. Додайте зазначені прянощі й томатну пасту, якщо вона є у складі.'),('Приготуйте з крупою','20–25 хв','Засипте крупу, залийте зазначеною гарячою водою та накрийте. Варіть на мінімальному вогні до готовності крупи. Перевірте курку: у центрі шматочка має бути не менше 74 °C. Дайте постояти під кришкою 7–10 хвилин.')]),
'RISOTTO':('Кремове ризото, у якому рис зберігає легку пружність.', [('Підготуйте основу','10 хв','Воду тримайте гарячою в окремій каструлі. На частині масла чи олії припустіть цибулю й основний овоч або гриби. Всипте сухий арборіо й прогрійте 1–2 хвилини.'),('Доведіть рис','20–25 хв','Підливайте гарячу воду невеликими порціями, помішуючи після кожного додавання. Коли рис стане м’яким, але не розвареним, зніміть з вогню й вмішайте решту масла та пармезан. Залиште на 2 хвилини.')]),
'PASTA':('Паста з насиченим соусом, що огортає кожну порцію.', [('Зваріть пасту','8–12 хв','У великій каструлі відваріть суху пасту за часом на упаковці. Перед відціджуванням залиште 100 г води для регулювання густоти соусу.'),('Зробіть соус і поєднайте','10–15 хв','На зазначеній олії або маслі приготуйте овочі, часник чи гриби за порадою. Додайте томати або вершки, якщо вони є у складі. Варені броколі, готовий тунець і каперси вмішуйте наприкінці. З’єднайте з пастою, за потреби додайте трохи збереженої води. Песто, зелень, сир і лимонний сік додавайте після вимкнення нагріву.')]),
'NOODLES':('Локшина зі швидко обсмаженими овочами та ароматним соусом.', [('Підготуйте локшину','5–10 хв','Якщо у складі вказана вже варена локшина, її повторно не відварюйте: розділіть грудочки. Суху локшину відваріть або замочіть за інструкцією на упаковці й відцідіть.'),('Обсмажте й поєднайте','8–12 хв','Овочі наріжте соломкою. На олії обсмажте гриби або тофу, якщо вони є, потім додайте овочі й готуйте 4–5 хвилин. Додайте локшину та соєвий соус, добре прогрійте. Кунжут, арахіс, зелень і сік лайма додайте наприкінці.')]),
'STEW':('Густе рагу з м’якими овочами та насиченою основою.', [('Підрум’яньте овочі','10 хв','Овочі наріжте кубиками. На зазначеній олії припустіть цибулю, додайте щільні овочі, часник і прянощі; обсмажуйте, помішуючи.'),('Протушкуйте','20–30 хв','Додайте томати та воду зі складу. Готуйте під кришкою на слабкому вогні до м’якості. Уже варені бобові та консервовану кукурудзу додайте на останні 8–10 хвилин. Дайте рагу постояти 3 хвилини.')]),
'CURRY':('Кремове карі з виразним ароматом прянощів.', [('Розкрийте аромат','5–7 хв','У зазначеній олії припустіть цибулю, часник та імбир, якщо вони є у складі. Додайте пасту карі або прянощі й прогрівайте, помішуючи, близько 30 секунд.'),('Зваріть карі','20–25 хв','Влийте кокосове молоко й зазначену воду. Додайте овочі кубиками і варіть до м’якості. Суху червону сочевицю промийте й готуйте в соусі 15–20 хвилин; готовий нут та шпинат додавайте наприкінці.')]),
'RICE_BOWL':('Рисова миска з контрастом теплої основи та соковитих додатків.', [('Приготуйте гарячі додатки','10–15 хв','Тофу або темпе обсушіть і наріжте. На олії обсмажте до рум’яності, додайте соєвий соус наприкінці. Броколі, якщо вона є у складі, окремо бланшуйте 3 хвилини.'),('Зберіть боул','5 хв','Уже варений рис добре прогрійте. Свіжі огірок і моркву тонко наріжте. Розкладіть рис, гарячий білковий складник та овочі, полийте соусом зі сковороди й посипте кунжутом, якщо він указаний.')]),
'ROAST_SALAD':('Теплі запечені овочі з ніжними та свіжими додатками.', [('Запечіть овочі','25–30 хв','Розігрійте духовку до 200 °C. Основний овоч підготуйте за порадою, змішайте з указаною олією й запікайте одним шаром до м’якості. Для соусів і заправок залиште частину олії.'),('Зберіть страву','5–7 хв','Готові бобові прогрійте окремо, якщо вони є у складі. З’єднайте з овочами та іншими додатками. Листя, сир, насіння, цитрусовий сік і йогуртовий або тахінний соус додавайте після зняття з нагріву.')]),
'BAKE_FISH':('Соковите рибне філе з м’якими запеченими овочами.', [('Підготуйте деко','8–10 хв','Розігрійте духовку до 190 °C. Філе без кісток обсушіть, овочі наріжте невеликими шматочками. Змастіть зазначеною олією, додайте прянощі й цитрус за порадою.'),('Запечіть рибу','18–25 хв','Викладіть філе й овочі в один шар та запікайте до готовності. Час залежить від товщини; орієнтир усередині риби — 63 °C. Йогуртовий соус, якщо він є у складі, подавайте холодним.')]),
'BAKE_CHICKEN':('Соковита запечена птиця з овочевим гарніром.', [('Підготуйте до запікання','10–15 хв','Розігрійте духовку до 190 °C. М’ясо без кісток наріжте шматочками до 2–3 см, овочі — невеликими скибками. Змішайте з указаними олією, сіллю та прянощами. Для запіканки додайте яєчно-йогуртову суміш і сир.'),('Запечіть','25–35 хв','Розподіліть у формі не надто товстим шаром та запікайте до готовності. Перевірте температуру в центрі найбільшого шматочка птиці — не менше 74 °C. Дайте постояти 5 хвилин.')]),
'TOFU':('Підрум’янений рослинний білок із соковитими овочами.', [('Обсмажте основний складник','7–10 хв','Тофу добре обсушіть і наріжте, темпе — наріжте тонкими скибками або розкришіть для скремблу. Обсмажте на зазначеній олії до рум’яності.'),('Додайте овочі та соус','7–10 хв','Додайте підготовлені овочі, щільні готуйте першими, шпинат — останнім. Соєвий соус, теріякі або розведену арахісову пасту додавайте за порадою; коротко прогрійте. Зелень і кунжут додайте перед подачею.')]),
'STIR_CHICKEN':('Швидко обсмажена птиця з ніжними овочами та соусом.', [('Обсмажте птицю','8–12 хв','М’ясо наріжте тонкими однаковими смужками. На розігрітій олії обсмажуйте невеликими порціями до повної готовності; перевірте, щоб усередині було не менше 74 °C.'),('Додайте овочі й соус','7–10 хв','Овочі та гриби обсмажте на тій самій сковороді, поверніть м’ясо. Вершки, кокосове молоко або інші складники соусу додавайте за порадою. Крохмаль завжди попередньо розмішуйте в холодній зазначеній воді. Прогрійте разом до загущення.')]),
'MEATBALL':('Невеликі соковиті м’ясні кульки у густому томатному соусі.', [('Сформуйте тефтелі','10–12 хв','Змішайте фарш із яйцем, сухарями та підготовленими цибулею або кабачком. Розділіть на однакові невеликі кульки. На олії злегка підрум’яньте з кількох боків.'),('Протушкуйте в соусі','20–25 хв','Додайте подрібнені помідори та зазначену воду. Накрийте і готуйте при слабкому кипінні до готовності; для фаршу з птиці температура в центрі має бути не менше 74 °C.')]),
'STUFFED':('Запечені овочі з м’якою круп’яною або сирною начинкою.', [('Підготуйте овочі та начинку','12–15 хв','Перець розріжте навпіл і видаліть насіння; кабачки розріжте вздовж та виберіть частину м’якоті; з томатів приберіть водянисту середину. Змішайте вже варені крупи чи бобові з підготовленими добавками. Сир і яйце використайте, якщо вони є у складі.'),('Наповніть і запечіть','25–35 хв','Розігрійте духовку до 190 °C. Наповніть овочі, поставте у форму, змащену зазначеною олією. Запікайте до повної м’якості овочевої оболонки; за наявності яйця перевірте 71 °C у начинці.')]),
'GRAIN_PATTIES':('Рум’яні котлети з круп або бобових, що зберігають м’яку серединку.', [('Зробіть масу','10–12 хв','Уже варені крупи або бобові добре відцідіть та частково розімніть. Овочі натріть або дрібно наріжте; гриби й цибулю попередньо обсмажте, якщо вказано в пораді. Змішайте з яйцем та борошном або сухарями.'),('Обсмажте котлети','12–16 хв','Сформуйте пласкі котлети. На вказаній олії смажте по 4–5 хвилин з кожного боку, потім коротко доготуйте під кришкою. Середина має повністю приготуватися, орієнтир за наявності яйця — 71 °C.')]),
'SPREAD':('Ніжна намазка з виразним основним смаком та легкою кислинкою.', [('Підготуйте основу','5–8 хв','Варені бобові ретельно відцідіть, сир розкришіть. Горіхи, зелень, часник та цитрус підготуйте за порадою. Термічно оброблені добавки спочатку остудіть.'),('Подрібніть і відрегулюйте густоту','3–5 хв','Складіть зазначені складники у чашу блендера. Збийте до кремової консистенції, додаючи тільки передбачені воду, йогурт, сік чи олію порціями. Для гуакамоле та дзадзикі основу розімніть виделкою, а подрібнені овочі й зелень вмішайте вручну.')]),
'CHIPS':('Тонкі запечені скибки з рум’яними краями та ароматом прянощів.', [('Підготуйте скибки','10 хв','Розігрійте духовку до 170 °C. Овочі наріжте однаково тонко й ретельно обсушіть. Змішайте з указаними олією та прянощами, викладіть на пергамент в один шар.'),('Підсушіть','20–25 хв','Запікайте, перевернувши приблизно посередині часу. Дрібні скибки виймайте раніше. Не допускайте потемніння; остаточної хрусткості чипси набувають після охолодження на решітці.')]),
'CRACKER':('Тонка хрустка випічка з виразною текстурою насіння або сиру.', [('Замісіть і розкачайте','15 хв','Змішайте борошно з сухими складниками. Додайте масло або олію та зазначені яйце чи воду. Зберіть тісто, не вимішуючи довго, і розкачайте між листами пергаменту до 2–3 мм.'),('Спечіть','15–20 хв','Наріжте смужками чи квадратами, перенесіть на деко. Випікайте при 180 °C до легкого рум’янцю, потім повністю остудіть, щоб випічка стала хрусткою.')]),
'ENERGY':('Щільні фруктово-горіхові кульки з м’якою текстурою.', [('Подрібніть складники','8–10 хв','Фініки звільніть від кісточок. Горіхи й пластівці спочатку подрібніть окремо, потім додайте фініки та какао. Зазначену воду додавайте потроху лише до пластичної маси.'),('Сформуйте кульки','10–20 хв','Вологими руками скачайте однакові невеликі кульки. Обкачайте у зазначеній кокосовій стружці або залишеній горіховій крихті. Потримайте у холодильнику 15–20 хвилин перед подачею.')]),
'FRUIT_BAKE':('Теплий фруктовий десерт із м’якою запеченою серединкою.', [('Підготуйте фрукти','8–10 хв','Розігрійте духовку до 180 °C. Фрукти помийте й підготуйте за порадою: видаліть кісточки або серцевину, зробіть поглиблення для начинки. Розкладіть у формі.'),('Запечіть','15–25 хв','Додайте передбачені начинку, прянощі та підсолоджувач. Запікайте до м’якості, не руйнуючи форму фруктів. Йогурт та свіжу зелень, якщо вони є, подавайте після випікання.')]),
'SMOOTHIE':('Густий прохолодний напій із натуральною фруктовою основою.', [('Підготуйте фрукти','4 хв','Помийте й очистіть фрукти від шкірки та кісточок, наріжте. Йогурт, молоко та воду тримайте охолодженими.'),('Збийте','2–3 хв','Складіть усі зазначені складники в блендер. Збийте до однорідності, вливаючи рідину порціями. Розлийте у склянки та подавайте одразу.')]),
}
ALIASES={
 'CORN_SAVORY':'CORN','FRITTER_SWEET':'FRITTER','CASSEROLE_SWEET':'CASSEROLE','TOAST_EGG':'TOAST','CROSTINI':'TOAST','COUSCOUS_SAVORY':'COUSCOUS','SALAD_EGG':'SALAD','SALAD_CHICKEN':'SALAD','SALAD_FISH':'SALAD','WARM_SALAD':'SALAD','FRUIT_SALAD':'SALAD','SOUP_CHICKEN':'SOUP','SOUP_FISH':'SOUP','LENTIL_CURRY':'CURRY','ROAST_BOWL':'ROAST_SALAD','FISH_GRAIN':'BAKE_FISH','SPREAD_COARSE':'SPREAD','WRAP_EGG':'WRAP','WRAP_CHICKEN':'WRAP','WRAP_HOT':'WRAP','FRIED_RICE_SHRIMP':'FRIED_RICE','NOODLES_CHICKEN':'NOODLES','NOODLES_SHRIMP':'NOODLES','PASTA_CHICKEN':'PASTA','STUFFED_VEG':'STUFFED','STEW_CHICKEN':'STEW','STEW_PORK':'STEW','STEW_BEEF':'STEW','STIR_BEEF':'STIR_CHICKEN','OMELET_ROLL':'OMELET',
}
PLANS.update({
'POTATO_BAKE':('Шарувата картопляна запіканка з рум’яною сирною скоринкою.', [('Підготуйте шари','15 хв','Розігрійте духовку до 190 °C. Картоплю наріжте слайсами 2–3 мм. Гриби й цибулю обсмажте на вказаній олії до випаровування вологи.'),('Запечіть','35–40 хв','Викладіть картоплю й гриби шарами, посоліть, залийте вершками. Накрийте форму фольгою на перші 25 хвилин. Потім зніміть фольгу, додайте сир і допікайте до повної м’якості картоплі.')]),
'POTATO_WEDGES':('Рум’яні картопляні часточки із густим грибним соусом.', [('Запечіть картоплю','30–35 хв','Розігрійте духовку до 200 °C. Картоплю наріжте однаковими тонкими часточками, обсушіть, змішайте з більшою частиною олії, паприкою та сіллю. Запікайте одним шаром, перевернувши посередині часу.'),('Зробіть соус','12–15 хв','На решті олії обсмажте цибулю та гриби до випаровування вологи. Додайте сметану й прогрійте на слабкому вогні без бурхливого кипіння. Подайте до повністю м’якої картоплі.')]),
'VEG_BAKE':('М’які запечені овочі із золотистим сирним верхом.', [('Підготуйте овочі та соус','12–15 хв','Розігрійте духовку до 190 °C. Овочі підготуйте за порадою: баклажан попередньо підпечіть, броколі бланшуйте 3 хвилини. Якщо є молоко й борошно, приготуйте соус: прогрійте масло з борошном 1 хвилину, поступово влийте молоко й проваріть до густоти.'),('Запечіть із сиром','20–25 хв','У форму викладіть овочі, передбачені томати чи молочний соус, розподіліть сир. Запікайте до повної м’якості овочів і рум’яного верху. Зелень додайте перед подачею.')]),
'STUFFED_POTATO':('М’який печений батат зі свіжим соусом та бобовою начинкою.', [('Запечіть батат','45–50 хв','Розігрійте духовку до 200 °C. Батат розріжте вздовж, змастіть олією й викладіть зрізом донизу на пергамент. Запікайте до повної м’якості.'),('Наповніть','5–7 хв','Варену квасолю прогрійте, йогурт змішайте із соком лайма та нарізаною кінзою. У м’якоті батату зробіть заглиблення, наповніть квасолею й полийте соусом.')]),
'FALAFEL':('Рум’яні запечені кульки з нуту та ароматної зелені.', [('Сформуйте кульки','12 хв','Нут ретельно відцідіть. Подрібніть із цибулею, часником, петрушкою та кмином короткими імпульсами. Вмішайте нутове борошно й сформуйте 12–14 невеликих кульок або пласких котлеток.'),('Запечіть і приготуйте соус','20–25 хв','Розкладіть на пергаменті, змастіть усією зазначеною олією. Випікайте при 200 °C, перевернувши посередині часу. Йогурт змішайте з лимонним соком і подайте окремо.')]),
'PATTIES_CHICKEN':('Ніжні домашні котлети з рум’яною скоринкою.', [('Замісіть фарш','10 хв','Дрібно подрібніть цибулю й зелень. Змішайте фарш із яйцем, сухарями й сіллю. Вологі овочі підготуйте за порадою, потім сформуйте 6 однакових котлет завтовшки до 2 см.'),('Приготуйте котлети','15–20 хв','На зазначеній олії обсмажте по 4–5 хвилин з кожного боку. Доготуйте під кришкою на слабкому вогні; для фаршу з птиці температура в центрі має бути не менше 74 °C.')]),
'MEATLOAF':('Соковитий м’ясний рулет із м’якою овочевою добавкою.', [('Сформуйте рулет','15 хв','Розігрійте духовку до 180 °C. Моркву натріть дрібно, цибулю подрібніть. Змішайте фарш з овочами, яйцями, сухарями, сіллю та половиною томатної пасти. Сформуйте рулет заввишки до 5 см на змащеному деку.'),('Запечіть','40–45 хв','Змастіть верх рештою томатної пасти. Запікайте до готовності: температура змішаного м’ясного фаршу в центрі має бути не менше 71 °C. Дайте рулету постояти 7–10 хвилин перед нарізанням.')]),
'MUSHROOM_PUREE':('Печериці з виразною скоринкою та ніжним коренеплідним пюре.', [('Зробіть пюре','20–25 хв','Очищену селеру наріжте кубиками й відваріть у технічній воді до м’якості. Воду злийте. Збийте селеру із зазначеними підігрітим молоком, маслом і частиною солі.'),('Обсмажте гриби','8–10 хв','Великі печериці обсушіть, злегка притисніть і підрум’яньте на олії з обох боків. Додайте подрібнений часник наприкінці. Подайте на пюре.')]),
'LASAGNA':('Соковита овочева запіканка з м’ясним томатним соусом.', [('Зробіть начинку','15–20 хв','Фарш обсмажте на олії з подрібненою цибулею до розсипчастості. Додайте томати й тушкуйте 10 хвилин, перевіривши готовність птиці до 74 °C. Кабачок наріжте довгими тонкими пластинами.'),('Зберіть і запечіть','30–35 хв','Розігрійте духовку до 190 °C. Чергуйте шари кабачка, м’ясного соусу й частини моцарели. Решту сиру розподіліть зверху. Запікайте до м’якості кабачка й гарячої середини, потім дайте постояти 7 хвилин.')]),
'SHRIMP':('Соковиті креветки у вершково-часниковій основі.', [('Підготуйте креветки','7 хв','Креветки очистіть, видаліть кишкову нитку та обсушіть. Часник наріжте тонко, петрушку подрібніть, із лимона вичавіть сік.'),('Швидко обсмажте','5–7 хв','Розтопіть масло. Обсмажте креветки в один шар по 2–3 хвилини з кожного боку, часник додайте після першого перевертання. Середина має стати непрозорою, орієнтир — 63 °C. Додайте сік і петрушку, подайте з указаним хлібом.')]),
'MUSSELS':('Ніжні мідії в густому ароматному томатному соусі.', [('Уваріть соус','15–18 хв','На олії припустіть цибулю, додайте часник та нарізані томати. Тушкуйте на помірному вогні до загущення.'),('Прогрійте мідії','3–5 хв','Додайте вже приготовлене м’ясо мідій і добре прогрійте в соусі. Не кип’ятіть довго, щоб воно не стало жорстким. Додайте базилік та подавайте з указаним хлібом.')]),
'RICE_ROLL':('Свіжі рисові роли з хрусткими овочами та ніжною начинкою.', [('Підготуйте начинку','12–15 хв','Овочі наріжте тонкою соломкою, листя обсушіть. Тофу обсмажте на зазначеній олії та остудіть; якщо у складі креветки — відваріть їх 3–5 хвилин до непрозорої середини й 63 °C, потім остудіть.'),('Згорніть роли','10 хв','Кожен лист рисового паперу коротко змочіть у теплій технічній воді за інструкцією на упаковці. Викладіть начинку, загніть боки та скрутіть. Соєвий соус змішайте із соком лайма й подайте окремо.')]),
'CUCUMBER_ROLL':('Прохолодні огіркові рулетики з м’якою сирною начинкою.', [('Підготуйте стрічки','8 хв','Огірок наріжте довгими стрічками овочечисткою та обсушіть. Горіхи й кріп дрібно подрібніть.'),('Сформуйте рулетики','7 хв','Змішайте вершковий сир із кропом, горіхами та невеликою частиною лимонного соку. Намастіть огіркові стрічки тонким шаром і згорніть. Решту соку подайте як легку заправку.')]),
'ONIGIRI':('Рисові трикутники з ніжною начинкою й ароматом норі.', [('Підготуйте рис і начинку','8 хв','Щойно зварений короткозернистий рис остудіть до теплого стану. Авокадо наріжте дрібними кубиками, норі — смужками. Кунжут коротко підсушіть і остудіть.'),('Зліпіть онігірі','8–10 хв','Змочіть руки, візьміть порцію рису, зробіть заглиблення з авокадо та закрийте рисом. Сформуйте невеликі трикутники, обгорніть норі й посипте кунжутом. Соєвий соус подайте окремо.')]),
'ROAST_CHICKPEAS':('Хрусткий запечений нут із пряною поверхнею.', [('Просушіть нут','10 хв','Розігрійте духовку до 200 °C. Варений нут відцідіть і ретельно обсушіть рушником. Змішайте з олією, сіллю й паприкою.'),('Запечіть','25–30 хв','Розкладіть одним шаром. Запікайте, перемішуючи кожні 10 хвилин, до хрусткої поверхні. Дайте трохи охолонути на відкритому деку; не накривайте, доки виходить пара.')]),
'LAVASH_CHIPS':('Легкі хрусткі трикутники з ароматом трав.', [('Підготуйте лаваш','5 хв','Розігрійте духовку до 180 °C. Лаваш змастіть олією, посипте зазначеними сіллю й спеціями, наріжте трикутниками.'),('Підсушіть','7–10 хв','Розкладіть на деку в один шар і запікайте до легкого рум’янцю. Діставайте тонші шматочки раніше. Остудіть без накривання.')]),
'VEG_SNACK':('Кабачкові кружальця із хрусткою сирною скоринкою.', [('Запаніруйте','12 хв','Розігрійте духовку до 200 °C. Кабачок наріжте кружальцями й обсушіть. Збийте яйце, сухарі змішайте з натертим пармезаном. Умочіть кабачок у яйце, потім у суху суміш.'),('Запечіть','18–22 хв','Викладіть на змащений зазначеною олією пергамент. Запікайте, обережно перевернувши посередині часу, до м’якості та повної готовності яєчної паніровки.')]),
'STUFFED_MUSHROOM':('Запечені гриби з ніжною сирною начинкою.', [('Зробіть начинку','12 хв','Розігрійте духовку до 190 °C. З печериць видаліть ніжки, дрібно наріжте та обсмажте їх на частині олії. Остудіть, змішайте з вершковим сиром, часником та петрушкою.'),('Запечіть гриби','18–20 хв','Капелюшки змастіть рештою олії, наповніть начинкою та посипте пармезаном. Запікайте до м’якості грибів і легкого рум’янцю сиру.')]),
'EGGPLANT_DIP':('М’який баклажановий дип із насиченим смаком тахіні.', [('Запечіть баклажани','35–40 хв','Розігрійте духовку до 210 °C. Баклажани наколіть виделкою й запечіть до повної м’якості. Трохи остудіть, виберіть м’якоть і відцідіть зайвий сік.'),('Зробіть дип','5 хв','М’якоть розімніть або коротко подрібніть із тахіні, лимонним соком, часником, указаними олією та сіллю. Не збивайте довго, щоб зберегти трохи текстури.')]),
'ROAST_DIP':('Оксамитовий морквяний дип із пряним акцентом.', [('Запечіть моркву','25–30 хв','Розігрійте духовку до 200 °C. Моркву наріжте невеликими брусочками, змішайте з олією та кмином. Запікайте до повної м’якості, потім трохи остудіть.'),('Збийте','5 хв','Подрібніть моркву з йогуртом, часником, лимонним соком та сіллю. Додавайте йогурт порціями, щоб контролювати густоту.')]),
'BAR':('Щільні фруктово-горіхові батончики без випікання.', [('Зробіть масу','12–15 хв','Фініки очистіть від кісточок, горіхи й пластівці подрібніть. Збийте разом із какао, підливаючи зазначену воду за потреби до пластичної маси.'),('Охолодіть','60 хв','Щільно утрамбуйте у невеликій формі, застеленій пергаментом. Поставте в холодильник на годину, потім наріжте на однакові батончики.')]),
'BAKED_BAR':('М’які вівсяні батончики з фруктовою солодкістю.', [('Змішайте','10 хв','Розігрійте духовку до 180 °C. Банан розімніть у пюре, курагу наріжте дрібно. З’єднайте з пластівцями, медом та насінням і щільно розподіліть шаром 2 см у формі на пергаменті.'),('Запечіть','22–25 хв','Випікайте до підрум’янених країв. Дайте повністю охолонути перед нарізанням, інакше батончики кришитимуться.')]),
'ROAST_NUTS':('Горіхи у тонкій медово-пряній оболонці.', [('Підготуйте','5 хв','Розігрійте духовку до 160 °C. Змішайте горіхи з медом та корицею, викладіть тонким шаром на пергамент.'),('Підсушіть','12–15 хв','Запікайте, перемішавши один раз. Не допускайте потемніння меду. Повністю остудіть на відкритому деку й розділіть злиплі горіхи.')]),
})
ALIASES.update({'RICE_ROLL_SHRIMP':'RICE_ROLL','PATTIES_BEEF':'PATTIES_CHICKEN'})
PLANS.update({
'GELATIN':('Прохолодний молочний десерт із ніжною пружною текстурою.', [('Приготуйте основу','15–20 хв','Желатин залийте зазначеною холодною водою на 10 хвилин. Молоко, вершки або кокосове молоко нагрійте із цукром до розчинення, не кип’ятіть. Зніміть з нагріву й розчиніть набухлий желатин у гарячій основі. Додайте ваніль, якщо вона є у складі.'),('Охолодіть','4 год','Розлийте по формочках, трохи остудіть і поставте у холодильник щонайменше на 4 години. Фрукти або ягоди подрібніть окремо й подайте зверху після застигання.')]),
'PUDDING':('Густий заварний пудинг без сирих яєць, м’який та однорідний.', [('Зваріть пудинг','10–12 хв','Приблизно чверть холодного молока змішайте з крохмалем і какао, якщо воно є. Решту молока нагрійте з цукром та кавою або ваніллю. Влийте крохмальну суміш, безперервно перемішуючи. Після появи перших бульбашок проваріть на слабкому вогні 1–2 хвилини; вмішайте зазначене масло або вершки.'),('Охолодіть','2 год','Розподіліть у невеликі миски. Накрийте поверхню плівкою в контакт, остудіть та охолоджуйте близько 2 годин. Передбачені свіжі ягоди додайте перед подачею.')]),
'RICE_PUDDING':('Кремовий рисовий десерт із м’якою молочною основою.', [('Прогрійте рис','15–20 хв','Уже зварений рис з’єднайте із зазначеним молоком та цукром. Варіть на найменшому вогні, часто помішуючи, доки суміш не стане кремовою. Родзинки додавайте під час варіння, якщо вони є у складі.'),('Завершіть десерт','5–10 хв','Зніміть з нагріву, вмішайте масло або кокосову стружку та прянощі, якщо вони зазначені. Дайте постояти 10 хвилин; фруктові добавки підготуйте за порадою.')]),
'SEMOLINA':('Густий манний десерт із яскравим ягідним соусом.', [('Заваріть основу','10 хв','Молоко нагрійте з половиною цукру. Тонкою цівкою всипте манку, постійно перемішуючи. Варіть 4–5 хвилин до густоти, розкладіть у змочені водою формочки й охолодіть у холодильнику близько години.'),('Зробіть соус','8–10 хв','Вишню без кісточок нагрійте з рештою цукру та половиною зазначеної води. Крохмаль розведіть у решті холодної води, влийте до вишні й проваріть 1 хвилину. Остудіть і подайте до пудингу.')]),
'CRUMBLE':('Соковита фруктова начинка під хрусткою масляною крихтою.', [('Зробіть начинку та крихту','15 хв','Розігрійте духовку до 180 °C. Фрукти підготуйте за порадою, змішайте з третиною цукру, а також крохмалем, якщо він є. Борошно перетріть із холодним маслом, рештою цукру та іншими сухими складниками до грубої крихти.'),('Запечіть','30–35 хв','Фрукти викладіть у форму, рівномірно засипте крихтою без утрамбовування. Запікайте до рум’яного верху й бульбашок фруктового соку по краях. Дайте постояти 10 хвилин.')]),
'BROWNIE':('Шоколадний десерт із насиченим смаком та щільною вологою крихтою.', [('Приготуйте тісто','12 хв','Розігрійте духовку до 175 °C. Шоколад із маслом обережно розтопіть і трохи остудіть. Яйця розмішайте з цукром, додайте шоколадну суміш, потім просіяні борошно й какао. Змішуйте лише до поєднання.'),('Випечіть','22–27 хв','Викладіть у форму приблизно 20×20 см на пергаменті. Випікайте до схопленого верху: на шпажці допустимі вологі крихти, але не сире тісто. Яєчна середина має приготуватися щонайменше до 71 °C. Повністю остудіть перед нарізанням.')]),
'CAKE':('Домашній кекс із м’якою рівномірною крихтою.', [('Замісіть тісто','12–15 хв','Розігрійте духовку до 175 °C. Яйця збийте з цукром. Додайте розм’якшене масло або олію, зазначені молочні складники та фруктове пюре чи сік за порадою. Окремо змішайте борошно, розпушувач і сухі прянощі, потім обережно з’єднайте. Вмішайте фрукти, моркву або горіхи.'),('Спечіть','35–45 хв','Перелийте у форму, застелену пергаментом, не заповнюючи вище двох третин. Випікайте до сухої шпажки в центрі. Якщо верх темнішає раніше, нещільно накрийте фольгою. Остудіть 10 хвилин у формі, потім на решітці.')]),
'MUFFIN':('Порційна випічка з м’якою серединою та рум’яною шапочкою.', [('Змішайте тісто','10–12 хв','Розігрійте духовку до 180 °C. Окремо змішайте борошно, цукор, розпушувач і прянощі; окремо — яйця, олію та молоко, йогурт або фруктове пюре. Швидко з’єднайте й обережно вмішайте добавки за порадою.'),('Випечіть порційно','22–25 хв','Розкладіть у 8–10 паперових або силіконових формочок, наповнюючи на дві третини. Випікайте до сухої шпажки й пружного верху. Остудіть перед вийманням.')]),
'COOKIE':('Домашнє печиво з підрум’яненими краями та ароматними додатками.', [('Зробіть тісто','10–12 хв','Розігрійте духовку до 180 °C. Розм’якшене масло змішайте з цукром, додайте яйце або сир, якщо вони є у складі. Вмішайте борошно, розпушувач і передбачені пластівці, пасту, насіння чи сухофрукти. Дайте постояти 5 хвилин.'),('Випечіть','12–16 хв','Сформуйте 16–20 невеликих пласких заготовок. Розкладіть на пергаменті з проміжками та випікайте до легкого рум’янцю. Яєчне тісто всередині має повністю пропектися. Остудіть 5 хвилин на деку, потім на решітці.')]),
'COCONUT_COOKIE':('Невеликі кокосові тістечка з рум’яною поверхнею.', [('Змішайте масу','12 хв','Розігрійте духовку до 170 °C. Яйця розмішайте з цукром, додайте борошно та кокосову стружку. Залиште на 10 хвилин для набухання.'),('Спечіть','14–18 хв','Сформуйте 16 невеликих гірок на пергаменті. Випікайте до світло-золотистої поверхні й повністю готової середини. Остудіть перед зняттям із дека.')]),
'SHORTBREAD':('Крихке масляне печиво з тонким цитрусовим ароматом.', [('Зробіть і охолодіть тісто','25 хв','Розітріть м’яке масло з цукровою пудрою та сіллю. Додайте дрібну лимонну цедру та борошно. Швидко зберіть у тісто, сформуйте плаский диск і охолодіть 15–20 хвилин.'),('Випечіть','15–18 хв','Розігрійте духовку до 170 °C. Розкачайте тісто до 5 мм, виріжте печиво та випікайте на пергаменті до світло-золотистих країв. Лимонний сік подайте окремо, як зазначено в пораді.')]),
'FRUIT_PAN':('Теплі фруктові скибки з легкою карамельною скоринкою.', [('Підготуйте скибки','8 хв','Ананас очистіть, видаліть тверду серцевину, наріжте скибками близько 1 см й обсушіть. Лайм підготуйте для соку, м’яту обірвіть.'),('Карамелізуйте','8–10 хв','На сковороді розтопіть масло, додайте цукор. Викладіть ананас одним шаром і підрум’яньте з обох боків. Зніміть з вогню, додайте лаймовий сік і м’яту.')]),
'PARFAIT':('Порційний десерт із ніжним кремом та соковитими фруктами.', [('Зробіть крем і начинку','8–10 хв','Сир або йогурт змішайте з указаними медом чи пудрою до гладкості. Фрукти й ягоди помийте, обсушіть і наріжте. Печиво покришіть, якщо воно є у складі.'),('Зберіть шарами','5–7 хв','У склянках чергуйте крем, фрукти та печиво або горіхи. Залиште частину фруктів для верху. Подавайте одразу або тримайте в холодильнику до подачі.')]),
'COFFEE_PARFAIT':('Ніжний кавовий десерт із просоченим печивом без сирих яєць.', [('Приготуйте крем','12 хв','Каву розчиніть у зазначеній гарячій воді та повністю охолодіть. Холодні вершки збийте з пудрою до м’яких піків. Обережно вмішайте маскарпоне до однорідності.'),('Зберіть і охолодіть','2 год','Печиво занурюйте в холодну каву на 1 секунду й укладайте шарами, чергуючи з кремом. Накрийте та охолоджуйте щонайменше 2 години. Какао просійте зверху перед подачею.')]),
'FROZEN':('Фруктове морозиво з м’яким вершковим смаком.', [('Приготуйте основу','10–15 хв','Фрукти очистіть і наріжте. Для бананового варіанта попередньо заморозьте шматочки 4 години, потім збийте з рештою складників. Для мангового — збийте свіжу м’якоть із йогуртом, медом та соком лайма.'),('Заморозьте','2–6 год','Перекладіть у контейнер із кришкою. Банановій основі після попереднього заморожування достатньо ще 1–2 годин; мангову заморожуйте 5–6 годин, перемішуючи щогодини перші три години. Перед подачею потримайте 5–10 хвилин у холодильнику.')]),
'SORBET':('Освіжальний фруктовий сорбет із яскравим смаком.', [('Зробіть основу','15–20 хв','Цукор розчиніть у зазначеній воді при нагріванні, потім повністю охолодіть. Фрукти підготуйте за порадою; ягоди подрібніть, цитрусовий сік відцідіть від кісточок. З’єднайте з сиропом.'),('Заморозьте','5–6 год','Перелийте в широкий контейнер. Заморожуйте, розбиваючи кристали виделкою щогодини перші 3 години. Перед подачею коротко збийте блендером за потреби та залиште на 5 хвилин для зручного порціонування.')]),
'AGAR':('Легке ягідне желе з виразним смаком малини.', [('Заваріть агар','10 хв','Агар змішайте з холодною зазначеною водою та цукром. Нагрійте, доведіть до кипіння і проваріть близько 2 хвилин, помішуючи. Малину збийте та окремо підігрійте, не доводячи до кипіння.'),('Поєднайте й охолодіть','60–80 хв','З’єднайте тепле малинове пюре з гарячою агарною основою та одразу розлийте по формочках. Дайте охолонути, потім поставте в холодильник до повного застигання.')]),
'CHOC_LOG':('Шоколадний десерт із хрусткими шматочками печива та горіхів.', [('Зробіть шоколадну масу','12–15 хв','Печиво й горіхи поламайте на шматочки різного розміру. Шоколад, масло та молоко обережно розтопіть на слабкому нагріві, не кип’ятіть. Трохи остудіть та змішайте з крихтою.'),('Сформуйте й охолодіть','3 год','Викладіть на харчову плівку або пергамент, сформуйте щільний циліндр і загорніть. Охолоджуйте щонайменше 3 години до нарізання. Наріжте скибками гострим ножем.')]),
'CHEESECAKE':('Ніжний запечений чизкейк із тонкою пісочною основою.', [('Зробіть основу та начинку','25 хв','Розігрійте духовку до 170 °C. З усього зазначеного борошна, 50 г масла та 25 г цукру зробіть крихту; додайте 10–15 г технічної води, утрамбуйте у форму 18–20 см і підпечіть 10 хвилин. Сир змішайте з йогуртом, рештою цукру, яйцями, ваніллю та лимонною цедрою. Рештою масла змастіть форму.'),('Випечіть та охолодіть','6 год','Вилийте начинку на основу. Зменште нагрів до 150 °C та випікайте 50–60 хвилин: краї мають схопитися, центр — злегка тремтіти без рідкої середини; яєчна начинка має досягти 71 °C. Остудіть близько години й охолоджуйте в холодильнику щонайменше 4 години.')]),
})
